<?php require_once __DIR__.'/../src/db.php';$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT * FROM panoramas WHERE id=?");$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Asset not found');}$tour=(int)($_GET['tour']??0);$sceneId=(int)($_GET['scene']??0);$hotspots=[];$tourScenes=[];$currentIndex=-1;if($tour&&$sceneId){$q=db()->prepare("SELECT h.*,ts.panorama_id target_panorama_id FROM hotspots h LEFT JOIN tour_scenes ts ON ts.id=h.target_scene_id WHERE h.scene_id=?");$q->execute([$sceneId]);$hotspots=$q->fetchAll();$q=db()->prepare("SELECT ts.id,ts.panorama_id,COALESCE(ts.title,p.title) title,p.image,p.preview,p.description FROM tour_scenes ts JOIN panoramas p ON p.id=ts.panorama_id WHERE ts.tour_id=? ORDER BY ts.sort_order,ts.id");$q->execute([$tour]);$tourScenes=$q->fetchAll();foreach($tourScenes as $i=>$ts)if((int)$ts['id']===$sceneId)$currentIndex=$i;}?>
